const palettes = ([
  ["#0098d8", "#0b3536", "#e5e7de", "#f54123"],
  ["#bfbabe", "#a63e14", "#558a86", "#f1f2f0"],
  ["#c7943e", "#fbfbfb", "#f67944", "#2677bb"],
  ["#777870", "#ec6b2d", "#333333", "#0d0f05"],
  ["#fbae17", "#f7772c", "#e4e6dd", "#dd6464"],
	["#f43530", "#46454b", "#00aabb", "#e0e5da"],
	["#f77e5e", "#303030", "#3dbd5d", "#f4f4f4"],
	["#db2f27", "#e6c700", "#007500", "#008cbc"],
]).map((p) => p.map((e) => e + "FF"));

let palette, sze, minWH, nf;

function setup() {
	createCanvas(windowWidth, windowHeight);
	palette = random(palettes)
	minWH = max(width, height);
	sze = random(minWH * 0.07, minWH * 0.12)
	noStroke()
	nf = random(0.001, 0.01)
	background(palette[0]);
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function draw() {
	const a = random(TWO_PI);
	const r = ~~random(minWH/sze/2) * sze;
	// const x = ~~random(width/sze) * sze;
	// const y = ~~random(height/sze) * sze;
	const x = cos(a) * r + width/2;
	const y = sin(a) * r + height/2;
	const n = noise(x * nf, y * nf) < 0.5;
	fill(palette[n ? 0 : 1]);
	circle(x, y, sze);
}
